from z3 import *

def main():
    # Enumerate worlds
    W, (s0, s1, s1e, s2, s3, s3e, s4, s4e, s5, s5e) = EnumSort('W', [
        's0', 's1', 's1e', 's2', 's3', 's3e', 's4', 's4e', 's5', 's5e'
    ])
    worlds = [s0, s1, s1e, s2, s3, s3e, s4, s4e, s5, s5e]
    name_of = {w: str(w) for w in worlds}

    # Accessibility relation (edges)
    edges = {
        (s0, s1), (s0, s1e),
        (s1, s2),
        (s1e, s1e),
        (s2, s3), (s2, s3e),
        (s3, s4), (s3, s4e),
        (s3e, s3e),
        (s4, s5), (s4, s5e),
        (s4e, s4e),
        (s5, s5),
        (s5e, s5e)
    }

    # Successor map (Python-level for distance constraints)
    succ = {w: [] for w in worlds}
    for (u, v) in edges:
        succ[u].append(v)

    # Propositions valuation (as sets of worlds)
    helpers_defined_set = {s1, s2, s3, s4, s5, s5e}
    continuity_ok_set = {s1, s2, s3, s4, s5, s5e}
    estimator_defined_set = {s2, s3, s4, s5, s5e}
    numeric_integrator_defined_set = {s3, s4, s5, s5e}
    smoke_passed_set = {s3, s4, s5, s5e}
    validation_computed_set = {s4, s5, s5e}
    thresholds_met_set = {s5}
    error_set = {s1e, s3e, s4e, s5e}

    # Helpers to build Boolean tests over world variables
    def is_in(w, S):
        if not S:
            return False
        return Or(*[w == c for c in S])

    def edge_ok(u, v):
        return Or(*[(u == a) & (v == b) for (a, b) in edges])

    def helpers_defined(w): return is_in(w, helpers_defined_set)
    def continuity_ok(w): return is_in(w, continuity_ok_set)
    def estimator_defined(w): return is_in(w, estimator_defined_set)
    def numeric_integrator_defined(w): return is_in(w, numeric_integrator_defined_set)
    def smoke_passed(w): return is_in(w, smoke_passed_set)
    def validation_computed(w): return is_in(w, validation_computed_set)
    def thresholds_met(w): return is_in(w, thresholds_met_set)
    def error_prop(w): return is_in(w, error_set)

    # Unrolling bound (<= number of worlds is complete for these CTL checks on a finite graph)
    N = len(worlds)

    # 1) EF(thresholds_met) witness from s0
    s_witness = Solver()
    path_w = [Const(f"w_path_{t}", W) for t in range(N + 1)]
    # initial
    s_witness.add(path_w[0] == s0)
    # transitions
    for t in range(N):
        s_witness.add(edge_ok(path_w[t], path_w[t+1]))
    # EF witness: some step hits thresholds_met
    hit_thresholds = Or(*[thresholds_met(path_w[t]) for t in range(N + 1)])
    s_witness.add(hit_thresholds)

    res_witness = s_witness.check()

    # 2) AG properties violation search (counterexample)
    s_ce = Solver()
    path = [Const(f"ce_path_{t}", W) for t in range(N + 1)]
    s_ce.add(path[0] == s0)
    for t in range(N):
        s_ce.add(edge_ok(path[t], path[t+1]))

    # Distance-to-thresholds variables per world for AG(!error -> EF thresholds_met)
    dist = {w: Int(f"dist_{name_of[w]}") for w in worlds}
    for w in worlds:
        s_ce.add(dist[w] >= -1, dist[w] <= N)
    for w in worlds:
        # If thresholds_met(w) then dist[w] == 0
        s_ce.add(Implies(is_in(w, thresholds_met_set), dist[w] == 0))
        # If not thresholds, then either -1 or 1 + successor's dist (with successor reachable)
        if w not in thresholds_met_set:
            succs = succ[w]
            if succs:
                reach_options = [And(dist[v] >= 0, dist[w] == dist[v] + 1) for v in succs]
                s_ce.add(Or(dist[w] == -1, Or(*reach_options)))
            else:
                # No successors: unreachable unless thresholds (but this case doesn't occur here)
                s_ce.add(dist[w] == -1)
        # If dist[w] == -1 then all successors must also be -1
        succs_all = succ[w]
        if succs_all:
            s_ce.add(Implies(dist[w] == -1, And(*[dist[v] == -1 for v in succs_all])))

    # Build violation formulas

    # V1: AG(error -> AX error) violated if exists t<N: error(path[t]) and not error(path[t+1])
    v1 = Or(*[
        And(error_prop(path[t]), Not(error_prop(path[t+1])))
        for t in range(N)
    ])

    # V2: AG(thresholds_met -> AX thresholds_met) violated if exists t<N: thresholds_met at t and not at t+1
    v2 = Or(*[
        And(thresholds_met(path[t]), Not(thresholds_met(path[t+1])))
        for t in range(N)
    ])

    # Helper: suffix_all_not(prop, start_idx) as Or over fixed start index choices:
    # Violation of AF(Q) from some t is: for all u in [t..N], Not(Q(path[u])).
    def af_violation(antecedent_fn, consequent_fn):
        clauses = []
        for t in range(N + 1):
            suffix_not = And(*[Not(consequent_fn(path[u])) for u in range(t, N + 1)])
            clauses.append(And(antecedent_fn(path[t]), suffix_not))
        return Or(*clauses) if clauses else BoolVal(False)

    # V3: AG((helpers_defined & continuity_ok) -> AF estimator_defined)
    v3 = af_violation(lambda w: And(helpers_defined(w), continuity_ok(w)),
                      estimator_defined)

    # V4: AG(estimator_defined -> AF (numeric_integrator_defined & smoke_passed))
    v4 = af_violation(estimator_defined,
                      lambda w: And(numeric_integrator_defined(w), smoke_passed(w)))

    # V5: AG((numeric_integrator_defined & smoke_passed) -> AF validation_computed)
    v5 = af_violation(lambda w: And(numeric_integrator_defined(w), smoke_passed(w)),
                      validation_computed)

    # V6: AG(validation_computed -> AF (thresholds_met or error))
    v6 = af_violation(validation_computed,
                      lambda w: Or(thresholds_met(w), error_prop(w)))

    # V7: AG(!error -> EF thresholds_met)
    # Violation: exists t with not error(path[t]) and dist[state] == -1 (i.e., no path to thresholds)
    v7_choices = []
    for t in range(N + 1):
        # Tie the world at time t to its dist being -1 and not error
        v7_choices.append(Or(*[
            And(path[t] == w, Not(is_in(w, error_set)), dist[w] == -1)
            for w in worlds
        ]))
    v7 = Or(*v7_choices)

    violation_any = Or(v1, v2, v3, v4, v5, v6, v7)
    s_ce.add(violation_any)

    res_ce = s_ce.check()

    # Reporting
    print("Verification results")
    print("--------------------")

    # EF witness
    print(f"EF(thresholds_met) from s0: {res_witness}")
    if res_witness == sat:
        m1 = s_witness.model()
        seq = [str(m1.evaluate(path_w[t])) for t in range(N + 1)]
        # find first hit index
        hit_idx = None
        for t in range(N + 1):
            # Evaluate thresholds_met at concrete world name
            # Compare with thresholds_met_set membership
            wt = m1.evaluate(path_w[t])
            # Find the world const mapped to this name
            # Because we printed string names, we can directly map via a reverse map
            # but easier: check by equality against constants
            hit = False
            for w in thresholds_met_set:
                if is_true(m1.evaluate(path_w[t] == w)):
                    hit = True
                    break
            if hit:
                hit_idx = t
                break
        print("  Witness path (length {}): {}".format(N, " -> ".join(seq)))
        if hit_idx is not None:
            print(f"  thresholds_met first holds at step {hit_idx} (state {seq[hit_idx]})")
        else:
            print("  Note: unexpected, thresholds_met not located precisely in model (should not happen).")
    else:
        print("  No witness path found within bound; EF might be false or bound insufficient.")

    # AG properties
    ag_all_hold = (res_ce == unsat)
    print(f"All AG properties hold (no bounded counterexample): {ag_all_hold}")
    if res_ce == sat:
        m2 = s_ce.model()
        seq = [str(m2.evaluate(path[t])) for t in range(N + 1)]
        which = []
        lbls = ["AG(error -> AX error)",
                "AG(thresholds_met -> AX thresholds_met)",
                "AG((helpers_defined & continuity_ok) -> AF estimator_defined)",
                "AG(estimator_defined -> AF (numeric_integrator_defined & smoke_passed))",
                "AG((numeric_integrator_defined & smoke_passed) -> AF validation_computed)",
                "AG(validation_computed -> AF (thresholds_met or error))",
                "AG(!error -> EF thresholds_met)"]
        vs = [v1, v2, v3, v4, v5, v6, v7]
        violated = []
        for i, v in enumerate(vs):
            val = m2.evaluate(v, model_completion=True)
            if is_true(val):
                violated.append(lbls[i])
        print("  Counterexample path (length {}): {}".format(N, " -> ".join(seq)))
        print("  Violated properties (within bound):")
        for p in violated:
            print("   -", p)
        # Optionally, help pinpoint an index for one violation
        # Try to find an index for the first AX violation if present
        if is_true(m2.evaluate(v1, model_completion=True)):
            for t in range(N):
                if is_true(m2.evaluate(And(error_prop(path[t]), Not(error_prop(path[t+1]))))):
                    print(f"    AX error violation at step {t} ({seq[t]} -> {seq[t+1]})")
                    break
        if is_true(m2.evaluate(v2, model_completion=True)):
            for t in range(N):
                if is_true(m2.evaluate(And(thresholds_met(path[t]), Not(thresholds_met(path[t+1]))))):
                    print(f"    AX thresholds_met violation at step {t} ({seq[t]} -> {seq[t+1]})")
                    break
    elif res_ce == unknown:
        print("  Solver returned unknown for AG counterexample search.")

if __name__ == "__main__":
    main()

